		Integer alternateTestValue = 800;

		ConcurrentSkipListMap<String,Integer> testObjects = new ConcurrentSkipListMap<String,Integer>();

		for( int i = 0; i < 50; i++)
		{
			testObjects.put(buildString(), generateTestNumber());
		}

