		assertEquals("70 : getReadLockCount()", THREADS_TO_SPAWN + 1, testLock.getReadLockCount());		// ... but there are THREADS_TO_SPAWN + 1 read locks held at the moment in total ...
		testLock.readLock().unlock();															
