		System.out.println("Casting " + mh.type() + " to " + mt + " -> did not throw the expected WrongMethodypeException");
		throw new ImplicitTestFailedException();
	}

	public static void compare(MethodHandle mh, MethodType mt, boolean expected, boolean result) {
