                    "Failed simdFill(a [len=%d], %s, 0, a.length): a[%d] = %s, expected %s",
                    a.length, x, i, a[i], x);
            }
        }

        // partial fill works
        for (int n = 0; n < max; n++) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= n - i; j++) { 
                    int x = (int)i + sourceData1(j);
                    fill(a, (int)0.0);
                    simdFill(a, x, i, j);
                    for (int k = 0; k < i; k++) {
                        checkThat(Integer.compare(a[k], (int)0.0) == 0,
                            "Failed simdFill(a [len=%d], %s, %d, %d): a[%d] = %s, expected %s",
                            a.length, x, i, j, k, a[k], (int)0.0);
                    }
