							.addModuleAddReads("com.test=ALL-UNNAMED")
						    .addModuleToModulepath("openjdk.test.modularity/bin/common-mods")
						    .addModuleToModulepath("openjdk.test.modularity/bin/tests")
						    .addRootModule("com.test")
