							.runClass(org.junit.runner.JUnitCore.class)
							.addArg("net.adoptopenjdk.test.modularity.junit.TestClassLoadingUsingResourceFiles")
						);
				break;
		}

	}

	public void tearDown(StfCoreExtension test) throws StfException {
	}
}

