					if(readIntoFile[i]!=null){
						bytesEXP += readIntoFile[i].remaining();
					}
                }

                // Write contents of readIntoFile array (all ByteBuffers) into file (gather)
                for (int i = 0; i < readIntoFile.length; i++)
