			}
		}
	}
	public void logMessage() {
		if (useLog) {
			if (logWriter != null) {
				logWriter.println();	
			}
		}
	}

	public void close() {
		if (useLog) {
			logMessage("Closing Logger");
			if (logWriter != null) {
				try {
					logWriter.close();
				} catch (Exception e) {}
			}
			if (os != null) {
				try {
					os.close();
				} catch (Exception e) {}
			}
		}
	}

	public void delete() {
		if (useLog) {
			close();
			if (logFile != null) {
				try {
					Files.deleteIfExists(logFile);
				} catch (IOException e) {}
			}
		}
	}

	@Override
	protected void finalize() throws Throwable {
		if (useLog) {
			close();
		}
	}
}

