public class CalendarTest {
	public void run() {
		Date d = new Date ();
		Calendar cal = Calendar.getInstance();

		cal.setTime(d);
		String tmpstr="";

		StringBuffer sb=new StringBuffer();
		int day = cal.get(Calendar.DAY_OF_WEEK);
		switch (day) {
			case 1:
				tmpstr="Sun";
				break;
			case 2:
				tmpstr="Mon";
				break;
			case 3:
				tmpstr="Tue";
				break;
			case 4:
				tmpstr="Wed";
				break;
