				tmpstr="Thu";
				break;
			case 6:
				tmpstr="Fri";
				break;
			case 7:
				tmpstr="Sat";
				break;
			default:
				Assert.fail("Invalid DAY_OF_WEEK value: " + day);
				break;
		}
		// System.out.println(tmpstr);

		sb.append (" weekday=\""+tmpstr+"\"");
		sb.append (" day=\""+cal.get(Calendar.DAY_OF_MONTH)+"\"");

		int month = cal.get(Calendar.MONTH);
		switch (month) {
			case 0:
				tmpstr="Jan";
				break;
			case 1:
				tmpstr="Feb";
				break;
			case 2:
				tmpstr="Mar";
				break;
			case 3:
				tmpstr="Apr";
				break;
			case 4:
				tmpstr="May";
				break;
			case 5:
				tmpstr="Jun";
				break;
			case 6:
				tmpstr="Jul";
				break;
			case 7:
				tmpstr="Aug";
				break;
			case 8:
				tmpstr="Sep";
				break;
			case 9:
				tmpstr="Oct";
				break;
			case 10:
				tmpstr="Nov";
				break;
			case 11:
				tmpstr="Dec";
				break;
			default:
				Assert.fail("Invalid MONTH value: " + month);
				break;
		}
		sb.append (" month=\""+tmpstr+"\"");

		sb.append (" time=\""+cal.get(Calendar.HOUR_OF_DAY)+
			":"+cal.get(Calendar.MINUTE)+
			":"+cal.get(Calendar.SECOND)+
			"."+cal.get(Calendar.MILLISECOND)+
			"\"");
		sb.append (" timezone=\""+cal.getTimeZone().getDisplayName(false,TimeZone.SHORT)+"\"");
		sb.append (" year=\""+cal.get(Calendar.YEAR)+"\"");
		sb.append (" ms=\""+d.getTime()+"\"");

		System.out.println(sb);
	}
