private int numberOccurrences(Collection<Object> values, Object value) {
		Iterator<Object> it = values.iterator();
		int count = 0;
		while (it.hasNext())
		{
			Object next = it.next();
			if (next.equals(value))
			{
				count++;
			}
		}
		return count;
	}

